mapper.select:
SELECT id, team_code, team_name, department_code, created_at, updated_at, deleted_at, delete_flag FROM teams WHERE delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
AND team_code = #{filter.teamCode}
AND team_name ILIKE '%' || #{filter.teamName} || '%'
AND (team_code ILIKE '%' || #{filter.search} || '%' OR team_name ILIKE '%' || #{filter.search} || '%')
ORDER BY ${filter.sortBy} ${filter.sortOrder}
LIMIT #{filter.size} OFFSET #{filter.offset}

SELECT COUNT(*) FROM teams WHERE delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
AND team_code = #{filter.teamCode}
AND team_name ILIKE '%' || #{filter.teamName} || '%'
AND (team_code ILIKE '%' || #{filter.search} || '%' OR team_name ILIKE '%' || #{filter.search} || '%')

mapper.update:
UPDATE teams
SET team_name = #{team.teamName},
    department_code = #{team.departmentCode},
    updated_at = #{team.updatedAt}
WHERE id = #{team.id}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM teams
    WHERE team_code = #{teamCode}
      AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)
